// CLAY OUTBOUND SCORING ENGINE — CONFIG
// Everything you might want to change lives in this one node. Nothing else in either
// workflow needs editing.
//
// The same config node ships in BOTH workflows ("01 score, enrich and route" and
// "02 classify replies and build the call list"). build.js regenerates both from this one
// file, and validate.js fails if they drift apart, so you never paste it between them.
//
// A blank key or id means that step is SKIPPED, never that the run fails. Both workflows run
// end to end on the invented demo prospects and demo replies, which is what lets this be
// shown on a screen-share before a single credential exists.

// ---------------------------------------------------------------- The safety switch
// Ships true. While it is true, nothing is written to Zoho and nothing is sent to a live
// Smartlead campaign or posted to the team: every payload is built in full and shown on a
// STOP node instead.
const TEST_RUN = true;
// Optional, only read while TEST_RUN is true. A Smartlead campaign id set here receives the
// pushes instead of the real campaigns (at most TEST_CAP leads). It can only ever REDIRECT a
// push, never cause a live one. Zoho is still not written in test mode.
const TEST_CAMPAIGN_ID = '';
const TEST_CAP = 3;

// ---------------------------------------------------------------- Mapping the Clay row
// Clay's HTTP API column posts one row as JSON to this workflow's webhook. You choose the key
// names in that column's body; list every name you might use for each field here, and the
// first one present on the row wins. Column names with spaces work as-is.
const CLAY_FIELDS = {
  clay_row_id:  ['clay_row_id', 'Clay Row ID', 'row_id', 'id'],
  first_name:   ['first_name', 'First Name', 'firstName'],
  last_name:    ['last_name', 'Last Name', 'lastName'],
  full_name:    ['full_name', 'Full Name', 'name', 'Name'],
  title:        ['title', 'Job Title', 'job_title', 'Title'],
  seniority:    ['seniority', 'Seniority'],
  email:        ['email', 'Work Email', 'work_email', 'Email'],
  phone:        ['phone', 'Mobile Phone', 'mobile_phone', 'Phone', 'Direct Phone'],
  linkedin_url: ['linkedin_url', 'LinkedIn URL', 'LinkedIn Profile', 'linkedin'],
  company:      ['company', 'Company Name', 'company_name', 'Company'],
  domain:       ['domain', 'Company Domain', 'company_domain', 'Website'],
  employees:    ['employees', 'Employee Count', 'employee_count', 'Company Size'],
  industry:     ['industry', 'Industry'],
  country:      ['country', 'Country', 'Location Country'],
  technologies: ['technologies', 'Technologies', 'Tech Stack', 'tech_stack'],
  // A Clay AI column's answer. If it names a persona from PERSONAS it is used as-is.
  ai_persona:   ['ai_persona', 'AI Persona', 'Persona']
};

// ---------------------------------------------------------------- Scoring (PLACEHOLDER)
// This table stands in for your own scoring method. It is a worked example, not your model:
// replace the rules, keep the shape. Each rule adds its points when its test matches;
// the total is clamped to 0..100.
//   equals    field value equals one of the values (case-insensitive)
//   contains  field value contains one of the words
//   between   a number between min and max, inclusive
//   any_of    a list field (technologies) contains any of the values
const SCORING = [
  { label: 'C-level',               field: 'seniority',    equals: ['c-level'],                  points: 30 },
  { label: 'VP',                    field: 'seniority',    equals: ['vp'],                       points: 25 },
  { label: 'Director / Head of',    field: 'seniority',    equals: ['director'],                 points: 20 },
  { label: 'Manager',               field: 'seniority',    equals: ['manager'],                  points: 10 },
  { label: 'Revenue-owning title',  field: 'title',        contains: ['sales', 'revenue', 'growth'], points: 10 },
  { label: 'Sweet-spot size',       field: 'employees',    between: [200, 1000],                 points: 25 },
  { label: 'Mid size',              field: 'employees',    between: [50, 199],                   points: 15 },
  { label: 'Large',                 field: 'employees',    between: [1001, 5000],                points: 15 },
  { label: 'Target industry',       field: 'industry',     contains: ['software', 'fintech', 'saas'], points: 20 },
  { label: 'Adjacent industry',     field: 'industry',     contains: ['logistics', 'healthcare'], points: 10 },
  { label: 'Uses a CRM we integrate', field: 'technologies', any_of: ['salesforce', 'hubspot', 'zoho'], points: 10 },
  { label: 'Core market',           field: 'country',      equals: ['united states', 'canada', 'united kingdom'], points: 5 }
];

// A disqualifier makes the prospect Reject whatever the score.
const DISQUALIFY = [
  { label: 'Student or intern',     field: 'title',     contains: ['intern', 'student'] },
  { label: 'Under 10 employees',    field: 'employees', between: [0, 9] },
  { label: 'Competitor',            field: 'domain',    equals: [] }
];

// Tier thresholds, highest first. Below the last one is Reject.
const TIERS = [
  { tier: 'A', min_score: 70 },
  { tier: 'B', min_score: 50 },
  { tier: 'C', min_score: 30 }
];

// Seniority when Clay did not send it, read off the title. First match wins.
const SENIORITY_FROM_TITLE = [
  { seniority: 'c-level',  words: ['chief', 'ceo', 'cro', 'cfo', 'coo', 'cto', 'founder', 'president'] },
  { seniority: 'vp',       words: ['vp', 'vice president'] },
  { seniority: 'director', words: ['director', 'head of'] },
  { seniority: 'manager',  words: ['manager', 'lead'] }
];

// Persona, first match on the title. A Clay AI column's answer (`ai_persona`) wins if it
// names one of these personas.
const PERSONAS = [
  { persona: 'Economic buyer',      words: ['ceo', 'founder', 'chief revenue', 'cro', 'vp sales', 'vp of sales', 'head of sales', 'sales director', 'director of sales'] },
  { persona: 'Operator',            words: ['revenue operations', 'revops', 'sales operations', 'operations'] },
  { persona: 'Technical evaluator', words: ['cto', 'it director', 'engineering', 'architect'] },
  { persona: 'Champion',            words: ['manager', 'lead'] }
];

// What a rep should do next, by tier and persona. `Tier|Persona` wins over `Tier|*`.
const RECOMMENDED_ACTION = {
  'A|Economic buyer': 'Call today, then sequence A',
  'A|*':              'Call within 24 hours, then sequence A',
  'B|*':              'Sequence B, call on any reply',
  'C|*':              'Nurture only: no enrichment, no sequence',
  'Reject|*':         'Do not contact'
};

// ---------------------------------------------------------------- Enrichment (the credits)
// Only these tiers are ever sent to paid enrichment, highest score first, and never more
// than ENRICH_BUDGET contacts in one run. The cap is enforced in code.
const ENRICH_TIERS  = ['A', 'B'];
const ENRICH_BUDGET = 4;
const CREDITS_PER_CONTACT = 1;
// Apollo's people/match reveals a verified work email (and a phone if asked). Blank key ->
// the demo enrichment stands in and the run says so.
const ENRICH_API_KEY = '';
const ENRICH_URL     = 'https://api.apollo.io/api/v1/people/match';
const REVEAL_PHONE   = false;   // phone reveals cost extra credits on most plans

// ---------------------------------------------------------------- Verification
// Every address is checked before it can reach a sending campaign. Anything the verifier did
// not answer counts as a hold: it fails closed.
const VERIFIER_API_KEY = '';
const VERIFIER_URL     = 'https://api.millionverifier.com/api/v3/';
const ACCEPT_STATUSES  = ['ok', 'valid', 'deliverable'];

// ---------------------------------------------------------------- Zoho CRM
// A Self Client in the Zoho API console gives a client id and secret; generate a refresh
// token with scope ZohoCRM.modules.ALL and ZohoCRM.coql.READ. The accounts base must match the
// data centre the org lives in (.com, .eu, .in, .com.au).
const ZOHO_CLIENT_ID     = '';
const ZOHO_CLIENT_SECRET = '';
const ZOHO_REFRESH_TOKEN = '';
const ZOHO_API_BASE      = 'https://www.zohoapis.com';
const ZOHO_ACCOUNTS_BASE = 'https://accounts.zoho.com';
const ZOHO_API_VERSION   = 'v8';
// Leads are upserted, matched on these fields in order, so a re-posted Clay row updates the
// lead instead of duplicating it.
const ZOHO_DUPLICATE_CHECK = ['Email'];
// Empty means Zoho's own workflow rules do NOT fire on these writes. Add 'workflow' to let them.
const ZOHO_TRIGGERS = [];
const LEAD_STATUS_BY_TIER = { A: 'Qualified - A', B: 'Qualified - B', C: 'Nurture' };
// Custom field API names from Zoho (Setup > Developer Hub > APIs > API names). Blank ->
// that field is not written.
const ZOHO_FIELDS = {
  fit_score: '',          // e.g. Fit_Score (number)
  tier: '',               // e.g. Fit_Tier (picklist A/B/C)
  persona: '',            // e.g. Persona
  recommended_action: '', // e.g. Recommended_Action
  clay_row_id: ''         // e.g. Clay_Row_ID
};
// Who owns a tier in Zoho (user ids). Blank -> Zoho's default owner.
const OWNER_BY_TIER = { A: '', B: '', C: '' };
// Reply states written back by workflow 02.
const REPLY_STATUS = {
  interested: 'Replied - Interested',
  not_now:    'Replied - Not now',
  referral:   'Replied - Referral',
  unsubscribe:'Unsubscribed',
  needs_human:'Replied - Needs review'
};

// ---------------------------------------------------------------- Smartlead
const SMARTLEAD_API_KEY  = '';
const SMARTLEAD_API_BASE = 'https://server.smartlead.ai/api/v1';
// One campaign per tier. Blank -> that tier is not pushed (C is never pushed).
const SMARTLEAD_CAMPAIGNS = { A: '', B: '' };
const SMARTLEAD_BATCH = 100;   // leads per request

// ---------------------------------------------------------------- Reply classification (02)
// OpenAI reads each reply into one class from REPLY_CLASSES. Blank key -> keyword rules only.
const OPENAI_API_KEY = '';
const OPENAI_MODEL   = 'gpt-4o-mini';
const OPENAI_URL     = 'https://api.openai.com/v1/chat/completions';
const REPLY_CLASSES  = ['interested', 'not_now', 'referral', 'unsubscribe', 'out_of_office', 'needs_human'];
// Below this confidence the model's answer is not trusted and a person reads the reply.
const MIN_AI_CONFIDENCE = 0.6;
// How many days out the follow-up task is due, by class.
const TASK_DUE_DAYS = { interested: 0, referral: 1, needs_human: 0, not_now: 60 };

// ---------------------------------------------------------------- Team notifications + call list
// A Slack (or Teams, or Google Chat) incoming-webhook URL. Blank -> shown, not posted.
const NOTIFY_WEBHOOK_URL = '';
// The morning call list: A-tier leads not yet contacted by phone, plus every interested or
// referral reply, ordered by who to ring first. Capped so it stays a list someone finishes.
const CALL_LIST_SIZE = 25;
const CALL_LIST_STATUSES = ['Replied - Interested', 'Replied - Referral', 'Qualified - A'];

// ---------------------------------------------------------------- Derived: do not edit below
const MODE = TEST_RUN !== true ? 'live' : (TEST_CAMPAIGN_ID.trim() !== '' ? 'test' : 'preview');
const ZOHO_AUTH_READY = ZOHO_CLIENT_ID.trim() !== '' && ZOHO_CLIENT_SECRET.trim() !== '' &&
                        ZOHO_REFRESH_TOKEN.trim() !== '';
const SMARTLEAD_READY = SMARTLEAD_API_KEY.trim() !== '';

const SETTINGS = {
  mode: MODE,
  test_campaign_id: TEST_CAMPAIGN_ID.trim(),
  test_cap: TEST_CAP,
  clay_fields: CLAY_FIELDS,
  scoring: SCORING,
  disqualify: DISQUALIFY,
  tiers: TIERS,
  seniority_from_title: SENIORITY_FROM_TITLE,
  personas: PERSONAS,
  recommended_action: RECOMMENDED_ACTION,
  enrich_tiers: ENRICH_TIERS,
  enrich_budget: ENRICH_BUDGET,
  credits_per_contact: CREDITS_PER_CONTACT,
  enrich_api_key: ENRICH_API_KEY,
  enrich_url: ENRICH_URL,
  reveal_phone: REVEAL_PHONE,
  verifier_api_key: VERIFIER_API_KEY,
  verifier_url: VERIFIER_URL,
  accept_statuses: ACCEPT_STATUSES,
  zoho_client_id: ZOHO_CLIENT_ID,
  zoho_client_secret: ZOHO_CLIENT_SECRET,
  zoho_refresh_token: ZOHO_REFRESH_TOKEN,
  zoho_api_base: ZOHO_API_BASE.replace(/\/+$/, ''),
  zoho_accounts_base: ZOHO_ACCOUNTS_BASE.replace(/\/+$/, ''),
  zoho_api_version: ZOHO_API_VERSION,
  zoho_duplicate_check: ZOHO_DUPLICATE_CHECK,
  zoho_triggers: ZOHO_TRIGGERS,
  lead_status_by_tier: LEAD_STATUS_BY_TIER,
  zoho_fields: ZOHO_FIELDS,
  owner_by_tier: OWNER_BY_TIER,
  reply_status: REPLY_STATUS,
  smartlead_api_key: SMARTLEAD_API_KEY,
  smartlead_api_base: SMARTLEAD_API_BASE.replace(/\/+$/, ''),
  smartlead_campaigns: SMARTLEAD_CAMPAIGNS,
  smartlead_batch: SMARTLEAD_BATCH,
  openai_api_key: OPENAI_API_KEY,
  openai_model: OPENAI_MODEL,
  openai_url: OPENAI_URL,
  reply_classes: REPLY_CLASSES,
  min_ai_confidence: MIN_AI_CONFIDENCE,
  task_due_days: TASK_DUE_DAYS,
  notify_webhook_url: NOTIFY_WEBHOOK_URL,
  call_list_size: CALL_LIST_SIZE,
  call_list_statuses: CALL_LIST_STATUSES,

  // Flags. Downstream nodes test these, never a key's emptiness.
  enrich_enabled: ENRICH_API_KEY.trim() !== '',
  verifier_enabled: VERIFIER_API_KEY.trim() !== '',
  zoho_auth_ready: ZOHO_AUTH_READY,
  zoho_enabled: ZOHO_AUTH_READY && MODE === 'live',
  smartlead_enabled: SMARTLEAD_READY && (MODE === 'live' || MODE === 'test'),
  ai_enabled: OPENAI_API_KEY.trim() !== '',
  notify_enabled: NOTIFY_WEBHOOK_URL.trim() !== '' && MODE !== 'preview'
};

// config sits IN the data path: whatever the trigger delivered is passed along untouched
// under `incoming`, one item in, one item out. A trigger with no payload (the schedule, a
// manual run) still produces one item, so $('config').first().json always resolves.
const incoming = $input.all().length ? $input.all().map((i) => i.json || {}) : [{}];
return incoming.map((payload) => ({ json: Object.assign({}, SETTINGS, { incoming: payload }) }));

// Turns whatever Clay posted into one clean prospect per row. CLAY_FIELDS in config says which
// key names mean which field, so a renamed Clay column is a config edit, not a code change.
//
// Accepts one row per request (Clay's HTTP API column), an array of rows, or { rows: [...] }.
// Nothing is dropped here: a row with no name or no company is kept, marked unusable with the
// reason, and stopped further down where it can be seen.
const cfg = $('config').first().json;
const F = cfg.clay_fields || {};

const pick = (row, field) => {
  for (const k of F[field] || [field]) {
    const v = row[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return '';
};
const str = (v) => String(v === undefined || v === null ? '' : v).trim();
const lower = (v) => str(v).toLowerCase();

const cleanDomain = (v) => lower(v).replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
const cleanEmail = (v) => {
  const e = lower(v);
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e) ? e : '';
};
const toList = (v) => (Array.isArray(v) ? v : str(v).split(/[,;|]/)).map(lower).filter(Boolean);
const toNumber = (v) => {
  if (typeof v === 'number') return v;
  const m = str(v).replace(/,/g, '').match(/\d+/g);   // "201-500" -> the lower bound
  return m ? Number(m[0]) : null;
};

function seniorityFrom(title, given) {
  const g = lower(given);
  if (g) {
    if (/c[-\s]?level|chief|owner|founder|cxo/.test(g)) return 'c-level';
    if (/vp|vice/.test(g)) return 'vp';
    if (/director|head/.test(g)) return 'director';
    if (/manager|lead/.test(g)) return 'manager';
  }
  const t = ' ' + lower(title).replace(/[^a-z ]/g, ' ') + ' ';
  for (const rule of cfg.seniority_from_title || []) {
    if (rule.words.some((w) => t.includes(' ' + w + ' ') || t.includes(' ' + w))) return rule.seniority;
  }
  return 'individual';
}

// Unwrap every incoming payload into rows.
const rows = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const payload = j.incoming || j;
  const body = payload.body !== undefined ? payload.body : payload;
  const list = Array.isArray(body) ? body : (Array.isArray(body.rows) ? body.rows : [body]);
  for (const r of list) rows.push({ row: r || {}, source: payload._source || 'Clay webhook' });
}

return rows.map(({ row, source }, i) => {
  let first = str(pick(row, 'first_name'));
  let last = str(pick(row, 'last_name'));
  const full = str(pick(row, 'full_name')) || [first, last].filter(Boolean).join(' ');
  if (!first && !last && full) {
    const parts = full.split(/\s+/);
    first = parts[0];
    last = parts.slice(1).join(' ');
  }
  const title = str(pick(row, 'title'));
  const p = {
    clay_row_id: str(pick(row, 'clay_row_id')) || 'row-' + (i + 1),
    first_name: first,
    last_name: last,
    full_name: full,
    title: title,
    seniority: seniorityFrom(title, pick(row, 'seniority')),
    email: cleanEmail(pick(row, 'email')),
    phone: str(pick(row, 'phone')),
    linkedin_url: str(pick(row, 'linkedin_url')),
    company: str(pick(row, 'company')),
    domain: cleanDomain(pick(row, 'domain')),
    employees: toNumber(pick(row, 'employees')),
    industry: str(pick(row, 'industry')),
    country: str(pick(row, 'country')),
    technologies: toList(pick(row, 'technologies')),
    ai_persona: str(pick(row, 'ai_persona')),
    _source: source
  };
  if (row._demo) p._demo = row._demo;

  const missing = [];
  if (!full) missing.push('no name');
  if (!p.company && !p.domain) missing.push('no company or domain');
  p._usable = missing.length === 0;
  p._hold = p._usable ? '' : 'not enough to score: ' + missing.join(', ');
  return { json: p };
});

// Scores every prospect on the fields Clay already sent, BEFORE anything is spent on them.
// That ordering is the whole credit argument: the tier decides who is worth enriching, so a
// C or a Reject never costs a credit.
//
// SCORING, DISQUALIFY, TIERS, PERSONAS and RECOMMENDED_ACTION all live in config. The score
// breakdown is kept on the prospect, so a rep (or Zoho) can see why someone is an A.
//
// Duplicates are caught here too, inside the run, on email, then LinkedIn, then name + domain.
// The first row wins; a later copy is held with the row it duplicates. Across runs, Zoho's
// upsert on ZOHO_DUPLICATE_CHECK is what stops a second lead being created.
const cfg = $('config').first().json;
const lower = (v) => String(v === undefined || v === null ? '' : v).toLowerCase().trim();

function matches(p, rule) {
  const v = p[rule.field];
  if (rule.any_of) {
    const list = Array.isArray(v) ? v.map(lower) : [lower(v)];
    return rule.any_of.some((w) => list.some((x) => x.includes(lower(w))));
  }
  if (rule.between) {
    const n = Number(v);
    return v !== null && v !== '' && !Number.isNaN(n) && n >= rule.between[0] && n <= rule.between[1];
  }
  const s = lower(v);
  if (!s) return false;
  if (rule.equals) return rule.equals.map(lower).includes(s);
  if (rule.contains) return rule.contains.some((w) => s.includes(lower(w)));
  return false;
}

function personaFor(p) {
  const names = (cfg.personas || []).map((x) => x.persona);
  const ai = (names.find((n) => lower(n) === lower(p.ai_persona)));
  if (ai) return { persona: ai, by: 'Clay AI column' };
  const t = ' ' + lower(p.title) + ' ';
  for (const x of cfg.personas || []) {
    if (x.words.some((w) => t.includes(lower(w)))) return { persona: x.persona, by: 'title' };
  }
  return { persona: 'Unclassified', by: 'no rule matched' };
}

function actionFor(tier, persona) {
  const map = cfg.recommended_action || {};
  return map[tier + '|' + persona] || map[tier + '|*'] || 'Review by hand';
}

const seen = {};
const keyOf = (p) => [
  p.email && 'email:' + p.email,
  p.linkedin_url && 'li:' + lower(p.linkedin_url).replace(/\/+$/, ''),
  p.full_name && (p.domain || p.company) && 'nd:' + lower(p.full_name) + '@' + lower(p.domain || p.company)
].filter(Boolean);

return $input.all().map((item) => {
  const p = Object.assign({}, item.json);

  if (!p._usable) {
    return { json: Object.assign(p, { score: 0, tier: 'Reject', persona: 'Unclassified',
      recommended_action: actionFor('Reject', ''), score_breakdown: [], _duplicate_of: '' }) };
  }

  const hits = (cfg.scoring || []).filter((r) => matches(p, r));
  const raw = hits.reduce((s, r) => s + Number(r.points || 0), 0);
  const score = Math.max(0, Math.min(100, raw));
  const dq = (cfg.disqualify || []).find((r) => matches(p, r));

  let tier = 'Reject';
  for (const t of cfg.tiers || []) { if (score >= t.min_score) { tier = t.tier; break; } }
  if (dq) tier = 'Reject';

  const who = personaFor(p);
  let dupOf = '';
  for (const k of keyOf(p)) { if (seen[k]) { dupOf = seen[k]; break; } }
  if (!dupOf) for (const k of keyOf(p)) seen[k] = p.clay_row_id;

  return {
    json: Object.assign(p, {
      score: score,
      tier: tier,
      persona: who.persona,
      persona_by: who.by,
      recommended_action: actionFor(tier, who.persona),
      score_breakdown: hits.map((r) => r.label + ' +' + r.points),
      disqualified_by: dq ? dq.label : '',
      _duplicate_of: dupOf,
      _hold: dupOf ? 'duplicate of ' + dupOf + ' in this run' : (dq ? 'disqualified: ' + dq.label : p._hold)
    })
  };
});

// Decides who is worth a credit. Only a prospect in ENRICH_TIERS (A and B by default) that
// is missing a work email is enriched, highest score first, and never more than
// ENRICH_BUDGET of them in one run. The cap is counted here, in code, not in a comment.
//
// Everyone else passes straight through with the reason they were not enriched, so the run
// summary can say exactly how many credits the ordering saved.
const cfg = $('config').first().json;
const tiers = cfg.enrich_tiers || ['A', 'B'];
const per = Number(cfg.credits_per_contact || 1);
const budget = Number(cfg.enrich_budget || 0);

const all = $input.all().map((i) => Object.assign({}, i.json));

const wanted = all
  .filter((p) => p._usable && !p._duplicate_of && tiers.includes(p.tier) && !p.email)
  .sort((a, b) => b.score - a.score);

let spent = 0;
const funded = new Set();
for (const p of wanted) {
  if (spent + per > budget) break;
  spent += per;
  funded.add(p.clay_row_id);
}

return all.map((p) => {
  let why = '';
  if (!p._usable) why = 'not usable';
  else if (p._duplicate_of) why = 'duplicate, never enriched';
  else if (!tiers.includes(p.tier)) why = 'tier ' + p.tier + ': not worth a credit';
  else if (p.email) why = 'already has a work email';
  else if (!funded.has(p.clay_row_id)) why = 'over ENRICH_BUDGET (' + budget + ' a run): enrich next run';

  const enrich = why === '';
  const out = Object.assign(p, { _needs_enrich: enrich, _enrich_skip: why });
  if (enrich) {
    out._enrich_body = {
      first_name: p.first_name,
      last_name: p.last_name,
      organization_name: p.company,
      domain: p.domain,
      linkedin_url: p.linkedin_url || undefined,
      reveal_personal_emails: false,
      reveal_phone_number: cfg.reveal_phone === true
    };
  }
  if (!p._hold && p.tier === 'Reject') out._hold = 'score ' + p.score + ' is below the C threshold';
  return { json: out };
});

// Everyone the plan did not fund passes through here untouched, carrying the reason in
// `_enrich_skip`: tier C, Reject, a duplicate, already has an email, or over the budget.
// Nothing is dropped; they rejoin the enriched prospects in the next node.
return $input.all().map((item) => ({ json: Object.assign({}, item.json, { _enriched: false }) }));

// No enrichment key, so the demo enrichment stands in: each invented prospect carries what the
// provider "would" have returned in `_demo`. The budget and the tier gate have already run,
// so the credits this run would have cost are exactly the rows arriving here.
//
// A real row (one without `_demo`) comes back "not enriched: no ENRICH_API_KEY", never with an
// invented address.
return $input.all().map((item) => {
  const p = Object.assign({}, item.json);
  const d = p._demo || {};
  if (d.email) p.email = String(d.email).toLowerCase();
  if (!p.phone && d.phone) p.phone = d.phone;
  p._enriched = !!p._demo;   // no credit is spent on a real row without a key
  p._enriched_by = p._demo ? 'demo enrichment (invented)' : 'none';
  p._enrich_result = p._demo ? (d.email ? 'email found' : 'no verified email found')
                             : 'not enriched: no ENRICH_API_KEY';
  delete p._enrich_body;
  return { json: p };
});

// Reads Apollo's people/match answer back onto the prospect it was asked about.
//
// A failed call, an empty match or a locked email comes back as "not found", never as a
// guess: a pattern-built first.last@domain is exactly the address that bounces and burns the
// sending domain. The credit was still spent, and the summary counts it.
const src = $('worth a credit?');
const replies = $input.all();

const prospectFor = (i) => {
  try { return src.itemMatching(i).json; } catch (e) { /* fall through */ }
  return (src.all(0)[i] || { json: {} }).json;
};

return replies.map((reply, i) => {
  const p = Object.assign({}, prospectFor(i));
  const body = reply.json || {};
  const person = body.person || {};
  const email = String(person.email || '').toLowerCase();
  const locked = !email || /not_unlocked|email_not_unlocked/.test(email);

  if (!locked) p.email = email;
  const phone = (person.phone_numbers && person.phone_numbers[0] && person.phone_numbers[0].sanitized_number) || '';
  if (!p.phone && phone) p.phone = phone;
  if (!p.linkedin_url && person.linkedin_url) p.linkedin_url = person.linkedin_url;

  p._enriched = true;
  p._enriched_by = 'Apollo people/match';
  p._enrich_result = locked
    ? (body.error ? 'call failed: ' + String(body.error.message || body.error).slice(0, 120) : 'no verified email found')
    : 'email found';
  delete p._enrich_body;
  return { json: p };
});

// Marks who needs a verifier call: an A or B prospect with an email, not a duplicate. Those
// are the only people who can reach a sending campaign, so they are the only ones worth
// paying to check. C tier goes to Zoho as nurture and is never emailed from here.
const cfg = $('config').first().json;
const tiers = cfg.enrich_tiers || ['A', 'B'];
return $input.all().map((item) => {
  const p = Object.assign({}, item.json);
  p._needs_verify = !!(p._usable && !p._duplicate_of && tiers.includes(p.tier) && p.email);
  return { json: p };
});

// Everyone the verifier was not called for. Three kinds arrive here:
//   * not needing it (C, Reject, duplicates, no email): passed through untouched
//   * an invented demo prospect: gets its demo verdict, so the demo shows the hold working
//   * a real prospect with no VERIFIER_API_KEY: marked "unverified", which holds it from the
//     campaign. Without a verifier nothing is emailed. That is the rule, not a fallback.
const cfg = $('config').first().json;
const accept = (cfg.accept_statuses || []).map((s) => String(s).toLowerCase());
return $input.all().map((item) => {
  const p = Object.assign({}, item.json);
  if (!p._needs_verify) return { json: p };
  if (p._demo && p._demo.verify) {
    p.email_status = String(p._demo.verify).toLowerCase();
    p._verified_by = 'demo verifier (invented)';
  } else {
    p.email_status = 'unverified';
    p._verified_by = 'none: no VERIFIER_API_KEY';
  }
  p._verified = accept.includes(p.email_status);
  return { json: p };
});

// Reads the verifier's verdict back onto the prospect. It fails closed: a timeout, a credit
// error or an answer it does not recognise becomes "unknown", which is held from the campaign.
// A bounced cold email costs more than a lead that waited a day.
const cfg = $('config').first().json;
const accept = (cfg.accept_statuses || []).map((s) => String(s).toLowerCase());
const src = $('verify with a key?');
const replies = $input.all();

const prospectFor = (i) => {
  try { return src.itemMatching(i).json; } catch (e) { /* fall through */ }
  return (src.all(0)[i] || { json: {} }).json;
};

return replies.map((reply, i) => {
  const p = Object.assign({}, prospectFor(i));
  const body = reply.json || {};
  const status = String(body.result || body.status || body.state || '').toLowerCase().trim() || 'unknown';
  p.email_status = status;
  p._verified = accept.includes(status);
  p._verified_by = 'verifier';
  return { json: p };
});

// The one place that decides where each prospect goes. Everything upstream only added facts;
// this node reads them all and routes:
//
//   Zoho CRM      A, B and C with an email that is not invalid. C lands as nurture.
//   Smartlead     A and B only, verified, and only if that tier has a campaign id.
//   held          everyone else, each with the reason, in one list.
//
// It returns ONE item carrying the whole run, because the Zoho upsert and the Smartlead push
// are both batch calls. Splitting here would reach them as several executions, each seeing
// part of the list.
const cfg = $('config').first().json;
const all = $input.all().map((i) => i.json);
const campaignTiers = Object.keys(cfg.smartlead_campaigns || {});

const crm = [];
const campaign = {};
const held = [];

for (const p of all) {
  const reasons = [];
  if (!p._usable || p._duplicate_of || p.tier === 'Reject') {
    held.push(Object.assign({}, p, { _where: 'nowhere', _why: p._hold || 'rejected' }));
    continue;
  }
  if (!p.email) {
    held.push(Object.assign({}, p, { _where: 'left in Clay',
      _why: (p._enrich_skip || p._enrich_result || 'no email') + ': nothing to match on in Zoho yet' }));
    continue;
  }
  if (p.email_status === 'invalid') {
    held.push(Object.assign({}, p, { _where: 'left in Clay',
      _why: 'email invalid: send it back through the waterfall' }));
    continue;
  }

  crm.push(p);

  if (!campaignTiers.includes(p.tier)) {
    reasons.push('tier ' + p.tier + ' is never sequenced');
  } else if (!p._verified) {
    reasons.push('email ' + (p.email_status || 'unverified') + ': held from the campaign');
  }
  if (reasons.length) {
    held.push(Object.assign({}, p, { _where: 'Zoho only', _why: reasons.join('; ') }));
    continue;
  }
  (campaign[p.tier] = campaign[p.tier] || []).push(p);
}

const by = (list, k) => list.reduce((m, p) => { m[p[k]] = (m[p[k]] || 0) + 1; return m; }, {});

return [{
  json: {
    crm: crm,
    campaign: campaign,
    held: held,
    counts: {
      received: all.length,
      by_tier: by(all.filter((p) => p._usable && !p._duplicate_of), 'tier'),
      to_zoho: crm.length,
      to_campaign: Object.values(campaign).reduce((s, l) => s + l.length, 0),
      held: held.filter((h) => h._where !== 'Zoho only').length,
      zoho_only: held.filter((h) => h._where === 'Zoho only').length,
      enriched: all.filter((p) => p._enriched).length,
      credits_used: all.filter((p) => p._enriched).length * Number(cfg.credits_per_contact || 1),
      credits_budget: Number(cfg.enrich_budget || 0),
      // What an enrich-every-row table would have spent on this batch, minus what was spent.
      credits_saved: (all.filter((p) => p._usable).length - all.filter((p) => p._enriched).length)
        * Number(cfg.credits_per_contact || 1)
    }
  }
}];

// The whole Zoho request, assembled as one object before anything is sent, so the exact body
// can be read on a STOP node when Zoho is not connected.
//
// Zoho specifics:
//   * POST /crm/v8/Leads/upsert takes { data, duplicate_check_fields, trigger }, up to 100
//     records. A record matching an existing lead on ZOHO_DUPLICATE_CHECK is UPDATED, not
//     duplicated: re-posting the same Clay row is safe.
//   * `trigger` empty means Zoho's own workflow rules do not fire on these writes.
//   * Owner is a lookup ({ id }), and a blank id is omitted: Zoho rejects { id: '' }.
//   * Custom fields are written only where ZOHO_FIELDS has an API name.
const cfg = $('config').first().json;
const run = $input.first().json;
const F = cfg.zoho_fields || {};

const records = (run.crm || []).slice(0, 100).map((p) => {
  const r = {
    Last_Name: p.last_name || p.full_name || 'Unknown',
    Email: p.email,
    Company: p.company || p.domain,
    Lead_Source: 'Clay',
    Lead_Status: (cfg.lead_status_by_tier || {})[p.tier] || 'Not Contacted',
    Description: 'Fit ' + p.score + ' (' + p.tier + ', ' + p.persona + '): ' + p.score_breakdown.join(', ') +
      '. Next: ' + p.recommended_action + '.'
  };
  if (p.first_name) r.First_Name = p.first_name;
  if (p.title) r.Designation = p.title;
  if (p.phone) r.Phone = p.phone;
  if (p.domain) r.Website = p.domain;
  if (p.employees) r.No_of_Employees = p.employees;
  if (p.industry) r.Industry = p.industry;
  if (p.country) r.Country = p.country;
  if (p.email_status === 'catch_all' || p.email_status === 'unknown' || p.email_status === 'unverified') {
    r.Description += ' Email ' + p.email_status + ': not sequenced.';
  }
  const owner = (cfg.owner_by_tier || {})[p.tier];
  if (owner) r.Owner = { id: owner };
  if (F.fit_score) r[F.fit_score] = p.score;
  if (F.tier) r[F.tier] = p.tier;
  if (F.persona) r[F.persona] = p.persona;
  if (F.recommended_action) r[F.recommended_action] = p.recommended_action;
  if (F.clay_row_id) r[F.clay_row_id] = p.clay_row_id;
  return r;
});

return [{
  json: {
    _count: records.length,
    _emails: records.map((r) => r.Email),
    _zoho: {
      url: cfg.zoho_api_base + '/crm/' + cfg.zoho_api_version + '/Leads/upsert',
      body: { data: records, duplicate_check_fields: cfg.zoho_duplicate_check || ['Email'],
        trigger: cfg.zoho_triggers || [] }
    }
  }
}];

// Zoho was not written: TEST_RUN is still true, the OAuth values are blank, or nobody in this
// run qualified. This node's output IS the result: the exact upsert body that would have gone
// to Zoho. Open it on a screen-share.
const cfg = $('config').first().json;
const j = $input.first().json;
return [{
  json: {
    _outcome: 'preview: nothing written to Zoho',
    _reason: j._count === 0 ? 'nobody in this run is going to Zoho'
      : (cfg.mode !== 'live' ? 'TEST_RUN is true, mode ' + cfg.mode
        : 'ZOHO_CLIENT_ID / ZOHO_CLIENT_SECRET / ZOHO_REFRESH_TOKEN is blank'),
    would_post_to: j._zoho.url,
    would_post: j._zoho.body
  }
}];

// Reads the access token out of the refresh-token exchange and puts it on the request built
// upstream. Zoho answers a failed refresh with HTTP 200 and an `error` key in the body, so the
// body is checked here: a node that only checks the status carries on and fails later with a
// confusing INVALID_TOKEN, which is the most common way a Zoho integration breaks quietly.
function readToken(res, request) {
  if (res.error || !res.access_token) {
    return {
      _authed: false,
      _why: res.error ? 'Zoho refused the refresh: ' + res.error : 'Zoho returned no access_token',
      _hint: res.error === 'invalid_client'
        ? 'ZOHO_CLIENT_ID and ZOHO_CLIENT_SECRET belong to a different data centre than ZOHO_ACCOUNTS_BASE'
        : res.error === 'invalid_code'
        ? 'the refresh token was revoked, or issued for different scopes'
        : 'check ZOHO_ACCOUNTS_BASE matches the region the Self Client was registered in'
    };
  }
  return Object.assign({}, request, { _authed: true, _access_token: res.access_token });
}
return [{ json: readToken($input.first().json || {}, $('build the Zoho upsert').first().json) }];

// The refresh-token exchange failed, so nothing was written. `_why` and `_hint` say which of
// the usual causes it is.
const j = $input.first().json || {};
return [{ json: { _outcome: 'could not authenticate with Zoho: nothing written', _why: j._why, _hint: j._hint } }];

// Zoho answers an upsert with one result per record, each with its own code, so a 200 on the
// request does NOT mean every record landed. Each result is read against the email it was
// sent for, and anything that is not SUCCESS is reported by name.
const sent = $('build the Zoho upsert').first().json._emails || [];
const res = $input.first().json || {};
const results = Array.isArray(res.data) ? res.data : [];

const rows = results.map((r, i) => ({
  email: sent[i] || '',
  code: r.code || '',
  action: r.action || '',
  zoho_id: (r.details && r.details.id) || '',
  message: r.code === 'SUCCESS' ? '' : (r.message || '') + (r.details ? ' ' + JSON.stringify(r.details).slice(0, 160) : '')
}));
const ok = rows.filter((r) => r.code === 'SUCCESS');

return [{
  json: {
    _outcome: 'written to Zoho',
    inserted: ok.filter((r) => r.action === 'insert').length,
    updated: ok.filter((r) => r.action === 'update').length,
    refused: rows.filter((r) => r.code !== 'SUCCESS'),
    results: rows
  }
}];

// Zoho refused the whole request. A visible step with the response on it, never a run that
// half-succeeded and said nothing. The usual three: INVALID_TOKEN (wrong data centre),
// MANDATORY_NOT_FOUND (the layout needs a field this does not send), INVALID_DATA (a
// Lead_Status in LEAD_STATUS_BY_TIER that does not exist in the org).
const j = $input.first().json || {};
const err = j.error || j;
return [{
  json: {
    _outcome: 'Zoho write failed: nothing was written',
    zoho_response: typeof err === 'string' ? err : JSON.stringify(err).slice(0, 600)
  }
}];

// One Smartlead request per campaign: POST /campaigns/{id}/leads with up to SMARTLEAD_BATCH
// leads. A and B go to their own campaigns, and the tier, persona, score and recommended
// action travel as custom fields so the copy can use them.
//
// In test mode every push is redirected to TEST_CAMPAIGN_ID and capped at TEST_CAP. That can
// only ever redirect a push, never cause a live one.
//
// Smartlead's own block and unsubscribe lists are always respected (the three `ignore_*`
// settings are false), so a lead who opted out of another campaign is not re-added here.
const cfg = $('config').first().json;
const run = $('decide what goes where').first().json;
const test = cfg.mode === 'test';

const toLead = (p) => ({
  first_name: p.first_name,
  last_name: p.last_name,
  email: p.email,
  phone_number: p.phone || undefined,
  company_name: p.company,
  website: p.domain || undefined,
  linkedin_profile: p.linkedin_url || undefined,
  custom_fields: { tier: p.tier, persona: p.persona, fit_score: String(p.score),
    recommended_action: p.recommended_action, clay_row_id: p.clay_row_id }
});

const pushes = [];
const skipped = [];
let testLeft = Number(cfg.test_cap || 3);

for (const [tier, list] of Object.entries(run.campaign || {})) {
  let campaignId = String((cfg.smartlead_campaigns || {})[tier] || '').trim();
  let leads = list;
  if (test) {
    campaignId = cfg.test_campaign_id;
    leads = list.slice(0, Math.max(0, testLeft));
    testLeft -= leads.length;
  }
  // In preview a blank campaign id still builds the push, with a placeholder, so the demo shows
  // the exact payload. The gate after this node never sends a placeholder.
  let placeholder = false;
  if (!campaignId) {
    if (cfg.mode !== 'preview') { skipped.push('tier ' + tier + ': no campaign id in SMARTLEAD_CAMPAIGNS'); continue; }
    campaignId = '<SMARTLEAD_CAMPAIGNS.' + tier + '>';
    placeholder = true;
  }
  for (let i = 0; i < leads.length; i += Number(cfg.smartlead_batch || 100)) {
    const chunk = leads.slice(i, i + Number(cfg.smartlead_batch || 100));
    pushes.push({
      _placeholder: placeholder,
      tier: tier,
      campaign_id: campaignId,
      count: chunk.length,
      emails: chunk.map((p) => p.email),
      _url: cfg.smartlead_api_base + '/campaigns/' + campaignId + '/leads',
      _body: {
        lead_list: chunk.map(toLead),
        settings: { ignore_global_block_list: false, ignore_unsubscribe_list: false,
          ignore_duplicate_leads_in_other_campaign: false }
      }
    });
  }
}

if (!pushes.length) return [{ json: { _none: true, skipped: skipped } }];
return pushes.map((p) => ({ json: Object.assign(p, { skipped: skipped }) }));

// Nothing was pushed to Smartlead: TEST_RUN is true with no TEST_CAMPAIGN_ID, the key is
// blank, or no tier had anyone ready. Every push that WOULD have gone is listed here in full.
const cfg = $('config').first().json;
const items = $input.all().map((i) => i.json);
const pushes = items.filter((p) => !p._none);
return [{
  json: {
    _outcome: 'preview: nothing pushed to Smartlead',
    _reason: !pushes.length ? 'no verified A or B lead with a campaign to go to'
      : (cfg.mode === 'preview' ? 'TEST_RUN is true and TEST_CAMPAIGN_ID is blank'
        : (!cfg.smartlead_enabled ? 'SMARTLEAD_API_KEY is blank' : 'a tier has no campaign id')),
    skipped: (items[0] || {}).skipped || [],
    would_push: pushes.map((p) => ({ tier: p.tier, campaign_id: p.campaign_id, url: p._url, body: p._body }))
  }
}];

// Smartlead answers each push with counts: how many were added, and how many it skipped
// because they were already in a campaign, blocked or unsubscribed. A failed call comes back
// with the error on it instead of stopping the run.
const src = $('pushing to Smartlead?');
return $input.all().map((reply, i) => {
  let push = {};
  try { push = src.itemMatching(i).json; } catch (e) { push = (src.all(0)[i] || { json: {} }).json; }
  const b = reply.json || {};
  const failed = !!(b.error || (b.ok === false));
  return {
    json: {
      _outcome: failed ? 'Smartlead refused the push' : 'pushed to Smartlead',
      tier: push.tier,
      campaign_id: push.campaign_id,
      sent: push.count,
      added: b.added_count !== undefined ? b.added_count : (b.upload_count !== undefined ? b.upload_count : null),
      skipped_by_smartlead: b.skipped_count !== undefined ? b.skipped_count : null,
      already_in_campaign: b.already_added_to_campaign !== undefined ? b.already_added_to_campaign : null,
      error: failed ? JSON.stringify(b.error || b).slice(0, 300) : ''
    }
  };
});

// One summary for the whole run: what came in, how it tiered, what the credits went on and
// what the ordering saved, what Zoho and Smartlead did with it, and everyone held back with
// the reason. It is the monitoring: a run that quietly did nothing still posts this.
const cfg = $('config').first().json;
const run = $('decide what goes where').first().json;
const c = run.counts;

const first = (name) => { try { return $(name).first().json; } catch (e) { return null; } };
const every = (name) => { try { return $(name).all().map((i) => i.json); } catch (e) { return []; } };

const zoho = first("read Zoho's answers") || first('STOP: preview - Zoho payload shown') ||
  first('STOP: Zoho rejected the write') || first('STOP: could not authenticate with Zoho') || {};
const pushed = every("read Smartlead's answer");
const preview = first('STOP: preview - Smartlead payload shown');

const tiers = ['A', 'B', 'C', 'Reject'].map((t) => t + ' ' + (c.by_tier[t] || 0)).join(' · ');
const zohoLine = zoho._outcome === 'written to Zoho'
  ? 'Zoho: ' + zoho.inserted + ' new, ' + zoho.updated + ' updated' + (zoho.refused.length ? ', ' + zoho.refused.length + ' refused' : '')
  : 'Zoho: ' + (zoho._outcome || 'not reached') + (zoho._reason ? ' (' + zoho._reason + ')' : '');
const slLine = pushed.length
  ? 'Smartlead: ' + pushed.map((p) => p.tier + ' ' + (p.added !== null ? p.added : p.sent) + ' added' + (p.error ? ' (error)' : '')).join(', ')
  : 'Smartlead: ' + (preview ? preview._outcome + ' (' + preview._reason + ')' : 'nothing to push');

const heldLines = run.held.map((h) => '• ' + (h.full_name || h.clay_row_id) + (h.company ? ', ' + h.company : '') +
  ': ' + h._where + ', ' + h._why);

const text = [
  (cfg.mode === 'live' ? '' : '[' + cfg.mode.toUpperCase() + '] ') + 'Clay scoring run: ' + c.received + ' rows',
  'Tiers: ' + tiers,
  'Enrichment: ' + c.credits_used + ' of ' + c.credits_budget + ' credits used, ' + c.credits_saved +
    ' saved against enriching every row',
  zohoLine,
  slLine,
  'Held: ' + (c.held + c.zoho_only),
  ...heldLines
].join('\n');

return [{
  json: {
    mode: cfg.mode,
    counts: c,
    zoho: zoho,
    smartlead: pushed.length ? pushed : (preview || {}),
    held: run.held.map((h) => ({ who: h.full_name || h.clay_row_id, company: h.company, tier: h.tier,
      where: h._where, why: h._why })),
    summary: text,
    _notify_body: { text: text }
  }
}];

// No NOTIFY_WEBHOOK_URL, or a preview run: the summary is here instead of in the team channel.
// Read `summary`.
const j = $input.first().json;
return [{ json: { _outcome: 'summary shown, not posted', summary: j.summary, counts: j.counts, held: j.held } }];

// Posted to the team channel. A webhook that answered with an error is reported, not assumed.
const b = $input.first().json || {};
const failed = !!(b.error || b.ok === false);
return [{ json: { _outcome: failed ? 'the team channel refused the post' : 'posted to the team channel',
  error: failed ? JSON.stringify(b.error || b).slice(0, 300) : '' } }];
